35	
36	/**
37	 * Mostly used as a facade for all Petclinic controllers
38	 * Also a placeholder for @Transactional and @Cacheable annotations
39	 *
40	 * @author Michael Isvy
41	 * @author Vitaliy Fedoriv
42	 */
43	@Service
44	public class ClinicServiceImpl implements ClinicService {
45	
46	    private final PetRepository petRepository;
47	    private final VetRepository vetRepository;
48	    private final OwnerRepository ownerRepository;
49	    private final VisitRepository visitRepository;
50	    private final SpecialtyRepository specialtyRepository;
51	    private final PetTypeRepository petTypeRepository;
52	    private final CustomerCodeGenerator customerCodeGenerator;
53	    private final HouseholdIdGenerator householdIdGenerator;
54	
55	    public ClinicServiceImpl(
56	        PetRepository petRepository,
57	        VetRepository vetRepository,
58	        OwnerRepository ownerRepository,
59	        VisitRepository visitRepository,
60	        SpecialtyRepository specialtyRepository,
61	        PetTypeRepository petTypeRepository,
62	        CustomerCodeGenerator customerCodeGenerator,
63	        HouseholdIdGenerator householdIdGenerator) {
64	        this.petRepository = petRepository;
65	        this.vetRepository = vetRepository;
66	        this.ownerRepository = ownerRepository;
67	        this.visitRepository = visitRepository;
68	        this.specialtyRepository = specialtyRepository;
69	        this.petTypeRepository = petTypeRepository;
70	        this.customerCodeGenerator = customerCodeGenerator;
71	        this.householdIdGenerator = householdIdGenerator;
72	    }
73	
74	    @Override
75	    @Transactional(readOnly = true)
76	    public Collection<Pet> findAllPets() throws DataAccessException {
77	        return petRepository.findAll();
78	    }
79	
80	    @Override
81	    @Transactional(readOnly = true)
82	    public Page<Pet> findPets(Pageable pageable) throws DataAccessException {
83	        return petRepository.findAll(pageable);
84	    }
85	
86	    @Override
87	    @Transactional
88	    public void deletePet(Pet pet) throws DataAccessException {
89	        petRepository.delete(pet);
90	    }
91	
92	    @Override
93	    @Transactional(readOnly = true)
94	    public Visit findVisitById(int visitId) throws DataAccessException {
95	        return findEntityById(() -> visitRepository.findById(visitId));
96	    }
97	
98	    @Override
99	    @Transactional(readOnly = true)
100	    public Collection<Visit> findAllVisits() throws DataAccessException {
101	        return visitRepository.findAll();
102	    }
103	
104	    @Override
105	    @Transactional
106	    public void deleteVisit(Visit visit) throws DataAccessException {
107	        visitRepository.delete(visit);
108	    }
109	
110	    @Override
111	    @Transactional(readOnly = true)
112	    public Vet findVetById(int id) throws DataAccessException {
113	        return findEntityById(() -> vetRepository.findById(id));
114	    }
115	
116	    @Override
117	    @Transactional(readOnly = true)
118	    public Collection<Vet> findAllVets() throws DataAccessException {
119	        return vetRepository.findAll();
120	    }
121	
122	    @Override
123	    @Transactional
124	    public void saveVet(Vet vet) throws DataAccessException {
125	        vetRepository.save(vet);
126	    }
127	
128	    @Override
129	    @Transactional
130	    public void deleteVet(Vet vet) throws DataAccessException {
131	        vetRepository.delete(vet);
132	    }
133	
134	    @Override
135	    @Transactional(readOnly = true)
136	    public Collection<Owner> findAllOwners() throws DataAccessException {
137	        return ownerRepository.findAll();
138	    }
139	
140	    @Override
141	    @Transactional(readOnly = true)
142	    public Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException {
143	        if (lastName != null) {
144	            return ownerRepository.findByLastName(lastName, pageable);
145	        }
146	        return ownerRepository.findAll(pageable);
147	    }
148	
149	    @Override
150	    @Transactional
151	    public void deleteOwner(Owner owner) throws DataAccessException {
152	        // Soft-delete: retain the record and flag it so it is excluded from duplicate/identity
153	        // checks, while remaining readable via findOwnerById.
154	        owner.setDeleted(true);
155	        ownerRepository.save(owner);
156	    }
157	
158	    @Override
159	    @Transactional(readOnly = true)
160	    public PetType findPetTypeById(int petTypeId) {
161	        return findEntityById(() -> petTypeRepository.findById(petTypeId));
162	    }
163	
164	    @Override
165	    @Transactional(readOnly = true)
166	    public Collection<PetType> findAllPetTypes() throws DataAccessException {
167	        return petTypeRepository.findAll();
168	    }
169	
170	    @Override
171	    @Transactional
172	    public void savePetType(PetType petType) throws DataAccessException {
173	        petTypeRepository.save(petType);
174	    }
175	
176	    @Override
177	    @Transactional
178	    public void deletePetType(PetType petType) throws DataAccessException {
179	        petTypeRepository.delete(petType);
180	    }
181	
182	    @Override
183	    @Transactional(readOnly = true)
184	    public Specialty findSpecialtyById(int specialtyId) {
185	        return findEntityById(() -> specialtyRepository.findById(specialtyId));
186	    }
187	
188	    @Override
189	    @Transactional(readOnly = true)
190	    public Collection<Specialty> findAllSpecialties() throws DataAccessException {
191	        return specialtyRepository.findAll();
192	    }
193	
194	    @Override
195	    @Transactional
196	    public void saveSpecialty(Specialty specialty) throws DataAccessException {
197	        specialtyRepository.save(specialty);
198	    }
199	
200	    @Override
201	    @Transactional
202	    public void deleteSpecialty(Specialty specialty) throws DataAccessException {
203	        specialtyRepository.delete(specialty);
204	    }
205	
206	    @Override
207	    @Transactional(readOnly = true)
208	    public Collection<PetType> findPetTypes() throws DataAccessException {
209	        return petRepository.findPetTypes();
210	    }
211	
212	    @Override
213	    @Transactional(readOnly = true)
214	    public Owner findOwnerById(int id) throws DataAccessException {
215	        return findEntityById(() -> ownerRepository.findById(id));
216	    }
217	
218	    @Override
219	    @Transactional(readOnly = true)
220	    public Pet findPetById(int id) throws DataAccessException {
221	        return findEntityById(() -> petRepository.findById(id));
222	    }
223	
224	    @Override
225	    @Transactional
226	    public void savePet(Pet pet) throws DataAccessException {
227	        pet.setType(findPetTypeById(pet.getType().getId()));
228	        petRepository.save(pet);
229	    }
230	
231	    @Override
232	    @Transactional
233	    public void saveVisit(Visit visit) throws DataAccessException {
234	        visitRepository.save(visit);
235	
236	    }
237	
238	    @Override
239	    @Transactional(readOnly = true)
240	    public Collection<Vet> findVets() throws DataAccessException {
241	        return vetRepository.findAll();
242	    }
243	
244	    @Override
245	    @Transactional
246	    public void saveOwner(Owner owner) throws DataAccessException {
247	        if (owner.isNew() && owner.getCustomerCode() == null) {
248	            String customerCode = customerCodeGenerator.generate(
249	                owner.getPostcode(), owner.getTelephone(), owner.getLastName());
250	            owner.setCustomerCode(
251	                customerCodeGenerator.deduplicate(customerCode, ownerRepository::existsByCustomerCode));
252	        }
253	        ownerRepository.save(owner);
254	
255	    }
256	
257	    @Override
258	    @Transactional(readOnly = true)
259	    public boolean existsOwnerWithIdentityKey(Owner owner) throws DataAccessException {
260	        String identityKey = owner.getIdentityKey();
261	        // Owners can only share an identity key when they share a (normalized) telephone, so it is
262	        // enough to compare against the owners already stored with the same telephone. Soft-deleted
263	        // owners are ignored, so a duplicate is allowed once the only match has been deleted.
264	        return ownerRepository.findByTelephone(owner.getTelephone()).stream()
265	            .filter(existing -> !existing.isDeleted())
266	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
267	    }
268	
269	    /**
270	     * Find an existing owner that this (not yet persisted) owner soft-matches: one sharing its last
271	     * name (ignoring case) and postcode but carrying a different telephone, so it is not a hard
272	     * identity-key duplicate. Returns the matching owner's id (the lowest when several match), or
273	     * {@code null} when the owner has no postcode or nothing matches.
274	     */
275	    @Override
276	    @Transactional(readOnly = true)
277	    public Integer findPossibleDuplicateOwnerId(Owner owner) throws DataAccessException {
278	        if (owner.getPostcode() == null) {
279	            return null;
280	        }
281	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
282	            .filter(existing -> !existing.isDeleted())
283	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
284	            .filter(existing -> !Objects.equals(owner.getTelephone(), existing.getTelephone()))
285	            .map(Owner::getId)
286	            .min(Integer::compareTo)
287	            .orElse(null);
288	    }
289	
290	    @Override
291	    @Transactional(readOnly = true)
292	    public boolean existsOwnerInHousehold(Owner owner) throws DataAccessException {
293	        return !findHouseholdMembers(owner).isEmpty();
294	    }
295	
296	    /**
297	     * The maximum number of owners allowed in a single city; once a city holds this many
298	     * owners it is considered at capacity and no further owners may be created there.
299	     */
300	    static final long CITY_CAPACITY = 50;
301	
302	    @Override
303	    @Transactional(readOnly = true)
304	    public boolean isCityAtCapacity(String city) throws DataAccessException {
305	        return ownerRepository.countByCityIgnoreCase(city) >= CITY_CAPACITY;
306	    }
307	
308	    /**
309	     * The maximum number of owners that may be created in a single day; once this many owners
310	     * have already been registered on a given business day no further owners may be created for
311	     * that day.
312	     */
313	    static final long DAILY_OWNER_LIMIT = 100;
314	
315	    @Override
316	    public boolean isRegistrationDateInFuture(LocalDate registrationDate) {
317	        return registrationDate != null && registrationDate.isAfter(LocalDate.now());
318	    }
319	
320	    @Override
321	    public LocalDate resolveRegistrationDate(LocalDate registrationDate) {
322	        LocalDate effectiveDate = registrationDate == null ? LocalDate.now() : registrationDate;
323	        return BusinessDay.rollForward(effectiveDate);
324	    }
325	
326	    @Override
327	    @Transactional(readOnly = true)
328	    public boolean isDailyOwnerLimitReached(LocalDate registrationDate) throws DataAccessException {
329	        return ownerRepository.countByRegistrationDate(registrationDate) >= DAILY_OWNER_LIMIT;
330	    }
331	
332	    /**
333	     * The number of owners that may be registered on a given day before further sign-ups for that
334	     * day are flagged with a bulk-signup warning. Once more than this many owners already exist for
335	     * the day, subsequent creates carry the warning.
336	     */
337	    static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
338	
339	    @Override
340	    @Transactional(readOnly = true)
341	    public boolean isBulkSignupWarranted(LocalDate registrationDate) throws DataAccessException {
342	        return ownerRepository.countByRegistrationDate(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
343	    }
344	
345	    @Override
346	    @Transactional(readOnly = true)
347	    public long countNamesakes(String firstName, String lastName) throws DataAccessException {
348	        return ownerRepository.findByLastNameIgnoreCase(lastName).stream()
349	            .filter(owner -> owner.getFirstName().equalsIgnoreCase(firstName))
350	            .count();
351	    }
352	
353	    /**
354	     * Assign the owner's deterministic {@code householdId}, derived from its last name and postcode,
355	     * so owners sharing a last name and postcode share the id automatically. Owners without a
356	     * postcode belong to no household and are left without an id.
357	     *
358	     * @return the assigned household id, or {@code null} when the owner has no postcode
359	     */
360	    @Override
361	    @Transactional
362	    public String assignHousehold(Owner owner) throws DataAccessException {
363	        if (owner.getPostcode() == null) {
364	            return null;
365	        }
366	        String householdId = householdIdGenerator.generate(owner.getLastName(), owner.getPostcode());
367	        owner.setHouseholdId(householdId);
368	        return householdId;
369	    }
370	
371	    /**
372	     * The number of members the owner's household will have once this (not yet persisted) owner is
373	     * created: the existing members sharing its household (last name and postcode), plus the owner
374	     * itself.
375	     */
376	    @Override
377	    @Transactional(readOnly = true)
378	    public long countHouseholdMembers(Owner owner) throws DataAccessException {
379	        return findHouseholdMembers(owner).size() + 1;
380	    }
381	
382	    /**
383	     * Find the existing owners that share {@code owner}'s household, i.e. those with the same last
384	     * name (ignoring case) and the same postcode. An owner without a postcode belongs to no
385	     * household, so no members are returned for it. Soft-deleted owners are excluded, so they
386	     * neither block a create as a household duplicate nor count towards the household size.
387	     */
388	    private List<Owner> findHouseholdMembers(Owner owner) {
389	        if (owner.getPostcode() == null) {
390	            return List.of();
391	        }
392	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
393	            .filter(existing -> !existing.isDeleted())
394	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
395	            .toList();
396	    }
397	
398	    @Override
399	    @Transactional(readOnly = true)
400	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
401	        return ownerRepository.findByLastName(lastName);
402	    }
403	
404	    @Override
405	    @Transactional(readOnly = true)
406	    public Collection<Visit> findVisitsByPetId(int petId) {
407	        return visitRepository.findByPetId(petId);
408	    }
409	
410	    @Override
411	    @Transactional(readOnly = true)
412	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
413	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
414	    }
415	
416	    private <T> T findEntityById(Supplier<T> supplier) {
417	        try {
418	            return supplier.get();
419	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
420	            // Just ignore not found exceptions for Jdbc/Jpa realization
421	            return null;
422	        }
423	    }
424	
425	}
