17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.samples.petclinic.service.IdempotencyStore;
40	import org.springframework.samples.petclinic.service.OwnerAuditor;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.servlet.http.HttpServletRequest;
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    private final OwnerAuditor ownerAuditor;
68	
69	    private final IdempotencyStore idempotencyStore;
70	
71	    private final HttpServletRequest request;
72	
73	    public OwnerRestControllerV1(ClinicService clinicService,
74	                                 OwnerMapper ownerMapper,
75	                                 PetMapper petMapper,
76	                                 VisitMapper visitMapper,
77	                                 OwnerAuditor ownerAuditor,
78	                                 IdempotencyStore idempotencyStore,
79	                                 HttpServletRequest request) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	        this.ownerAuditor = ownerAuditor;
85	        this.idempotencyStore = idempotencyStore;
86	        this.request = request;
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
92	        Collection<Owner> owners;
93	        if (lastName != null) {
94	            owners = this.clinicService.findOwnerByLastName(lastName);
95	        } else {
96	            owners = this.clinicService.findAllOwners();
97	        }
98	        if (owners.isEmpty()) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
107	        Owner owner = this.clinicService.findOwnerById(ownerId);
108	        if (owner == null) {
109	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
110	        }
111	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
117	        String idempotencyKey = this.request.getHeader("Idempotency-Key");
118	        ResponseEntity<OwnerDto> replay = replayCreatedOwner(idempotencyKey);
119	        if (replay != null) {
120	            return replay;
121	        }
122	        HttpHeaders headers = new HttpHeaders();
123	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
124	        if (this.clinicService.isRegistrationDateInFuture(owner.getRegistrationDate())) {
125	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
126	        }
127	        owner.setRegistrationDate(this.clinicService.resolveRegistrationDate(owner.getRegistrationDate()));
128	        if (this.clinicService.isDailyOwnerLimitReached(owner.getRegistrationDate())) {
129	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
130	        }
131	        if (this.clinicService.isCityAtCapacity(owner.getCity())) {
132	            return new ResponseEntity<>(HttpStatus.CONFLICT);
133	        }
134	        // Assign the deterministic householdId (derived from last name and postcode) so owners in
135	        // the same household share it automatically and it forms part of the identity key.
136	        this.clinicService.assignHousehold(owner);
137	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
138	        // A second owner in an existing household (same last name and postcode) is a household
139	        // duplicate; reject it unless the client declares the shared household, in which case it is
140	        // created as a declared member.
141	        if (this.clinicService.existsOwnerInHousehold(owner) && !declaredHouseholdMember) {
142	            return new ResponseEntity<>(HttpStatus.CONFLICT);
143	        }
144	        // Reject an exact duplicate: an owner whose whole identity key (normalized telephone,
145	        // email and householdId) already exists.
146	        if (this.clinicService.existsOwnerWithIdentityKey(owner)) {
147	            return new ResponseEntity<>(HttpStatus.CONFLICT);
148	        }
149	        owner.setNamesakeCount((int) this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
150	        owner.setHouseholdSize((int) this.clinicService.countHouseholdMembers(owner));
151	        owner.setBulkSignupWarning(this.clinicService.isBulkSignupWarranted(owner.getRegistrationDate()));
152	        // Flag a soft match unless this is a declared household member (a declared member is not a
153	        // suspected duplicate): an existing owner sharing this owner's last name and postcode with a
154	        // different telephone.
155	        if (!declaredHouseholdMember) {
156	            Integer possibleDuplicateOf = this.clinicService.findPossibleDuplicateOwnerId(owner);
157	            owner.setPossibleDuplicate(possibleDuplicateOf != null);
158	            owner.setPossibleDuplicateOf(possibleDuplicateOf);
159	        }
160	        this.clinicService.saveOwner(owner);
161	        this.ownerAuditor.auditCreated(owner);
162	        this.idempotencyStore.record(idempotencyKey, owner.getId());
163	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
164	        headers.setLocation(UriComponentsBuilder.newInstance()
165	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
166	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
167	    }
168	
169	    /**
170	     * If {@code idempotencyKey} was already used to create an owner, return that original owner
171	     * with {@code 200 OK} so a repeated create replays the first result instead of creating a
172	     * duplicate. Returns {@code null} when there is nothing to replay (no key, or key unseen).
173	     */
174	    private ResponseEntity<OwnerDto> replayCreatedOwner(String idempotencyKey) {
175	        return this.idempotencyStore.find(idempotencyKey)
176	            .map(this.clinicService::findOwnerById)
177	            .map(owner -> new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK))
178	            .orElse(null);
179	    }
180	
181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Override
183	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
184	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
185	        if (currentOwner == null) {
186	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
187	        }
188	        currentOwner.setAddressLine1(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine1()));
189	        currentOwner.setAddressLine2(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine2()));
190	        currentOwner.setAddress(ownerMapper.composeAddress(ownerFieldsDto));
191	        currentOwner.setCity(ownerFieldsDto.getCity());
192	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
193	        currentOwner.setLastName(ownerFieldsDto.getLastName());
194	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
195	        this.clinicService.saveOwner(currentOwner);
196	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
197	    }
198	
199	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
200	    @Transactional
201	    @Override
202	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
203	        Owner owner = this.clinicService.findOwnerById(ownerId);
204	        if (owner == null) {
205	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
206	        }
207	        this.clinicService.deleteOwner(owner);
208	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
209	    }
210	
211	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
212	    @Override
213	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
214	        Owner owner = this.clinicService.findOwnerById(ownerId);
215	        if (owner == null) {
216	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
217	        }
218	        HttpHeaders headers = new HttpHeaders();
219	        Pet pet = petMapper.toPet(petFieldsDto);
220	        owner.setId(ownerId);
221	        pet.setOwner(owner);
222	        pet.getType().setName(null);
223	        this.clinicService.savePet(pet);
224	        PetDto petDto = petMapper.toPetDto(pet);
225	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
226	            .buildAndExpand(pet.getId()).toUri());
227	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
228	    }
229	
230	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
231	    @Override
232	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
233	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
234	        if (currentOwner != null) {
235	            Pet currentPet = this.clinicService.findPetById(petId);
236	            if (currentPet != null) {
237	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
238	                currentPet.setName(petFieldsDto.getName());
239	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
240	                this.clinicService.savePet(currentPet);
241	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
242	            }
243	        }
244	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
245	    }
246	
247	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
248	    @Override
249	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
250	        HttpHeaders headers = new HttpHeaders();
251	        Visit visit = visitMapper.toVisit(visitFieldsDto);
252	        Pet pet = new Pet();
253	        pet.setId(petId);
254	        visit.setPet(pet);
255	        this.clinicService.saveVisit(visit);
256	        VisitDto visitDto = visitMapper.toVisitDto(visit);
257	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
258	            .buildAndExpand(visit.getId()).toUri());
259	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
260	    }
261	
262	
263	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
264	    @Override
265	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
266	        Owner owner = this.clinicService.findOwnerById(ownerId);
267	        if (owner != null) {
268	            Pet pet = owner.getPet(petId);
269	            if (pet != null) {
270	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
271	            }
272	        }
273	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
274	    }
275	}
